SELECT FifoStock.Prdt, [1ISIN].SYM, FifoStock.AvQty AS [In Stock], ([Rt]/[PQty]*[AvQty]) AS [Value], [value]/IIf([Currency]="EUR",1,[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]) AS Valueâ‚¬, IIf([Currency]="EUR",1,[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]) AS Change, [ValueLive]/[change] AS ValueLiveâ‚¬, Realtick.[BETA ( SECURITY )] AS Beta, IIf([Beta]=0,IIf([1ISIN]![IdD]=3,-1,1),[Beta]) AS BetaN, [Valueliveâ‚¬]*[betaN] AS BetaPon, Realtick.[C_LAST_PRICE_REF ( LIVEQUOTE )] AS Live, ([live]*[AvQty]) AS ValueLive
FROM (Change INNER JOIN ((((((Realtick RIGHT JOIN ((FifoStock INNER JOIN 1ISIN ON FifoStock.Prdt = [1ISIN].ISIN) LEFT JOIN 1Currency ON [1ISIN].IdC = [1Currency].IdC) ON Realtick.[ISIN_NO ( LIVEQUOTE )] = [1ISIN].ISIN) LEFT JOIN 1Assett ON [1ISIN].IdA = [1Assett].IdA) LEFT JOIN 1Direction ON [1ISIN].IdD = [1Direction].IdD) LEFT JOIN 1Region ON [1ISIN].IdR = [1Region].IdR) LEFT JOIN 1Sector ON [1ISIN].IdS = [1Sector].IdS) LEFT JOIN 1Type ON [1ISIN].IdT = [1Type].IdT) ON Change.IdC = [1ISIN].IdC) LEFT JOIN qStrategy ON [1ISIN].ISIN = qStrategy.ISIN;
